import pytest
import json
import redis

# Create a Redis client
def create_redis_client():
    return redis.Redis(host='localhost', port=6379, db=0)

# Load the Redis state from the JSON file
def load_redis_state(filename):
    with open(filename, 'r') as f:
        return json.load(f)

# Test the Redis state
def test_redis_state():
    redis_client = create_redis_client()
    redis_state = load_redis_state('redis_state.json')

    # Test strings
    for key, value in redis_state['strings'].items():
        assert redis_client.get(key) == value.encode('utf-8')

    # Test hashes
    for key, value in redis_state['hashes'].items():
        assert redis_client.hgetall(key) == value

    # Test lists
    for key, value in redis_state['lists'].items():
        assert redis_client.lrange(key, 0, -1) == value

# Test the health metrics
def test_health_metrics():
    redis_client = create_redis_client()
    health_metrics = json.loads(redis_client.get('hdm:health_metrics').decode('utf-8'))

    assert 'memory_percent' in health_metrics
    assert 'cpu_percent' in health_metrics
    assert 'anomalies' in health_metrics

    assert isinstance(health_metrics['memory_percent'], (int, float))
    assert isinstance(health_metrics['cpu_percent'], (int, float))
    assert isinstance(health_metrics['anomalies'], list)

# Test the telemetry data
def test_telemetry_data():
    redis_client = create_redis_client()

    total_requests = int(redis_client.get('telemetry:total_requests').decode('utf-8'))
    total_bytes = int(redis_client.get('telemetry:total_bytes').decode('utf-8'))
    recoveries = int(redis_client.get('telemetry:recoveries').decode('utf-8'))

    assert total_requests >= 0
    assert total_bytes >= 0
    assert recoveries >= 0

# Run the tests
pytest.main([__file__])
